# Which modules a school has moves from columns on the school into a catalog
# and a grant per school:  SchoolAdmin 1 -- 0..* SchoolModule 0..* -- 1 Module.
# Every school gets exactly what it had: the five modules every school has
# always had, and hostel / extra billing as their columns say. The two columns
# stay (unread, mirrored) for one release so the previous release's code is
# right during the deploy and after a rollback.
#
# Frozen here, not imported: a migration must mean the same thing forever.
CATALOG = (
    ("exams", "Exams & results"),
    ("payroll", "Payroll"),
    ("accounting", "Accounting"),
    ("library", "Library"),
    ("inventory", "Inventory"),
    ("hostel", "Hostel"),
    ("extra_billing", "Extra billing"),
)
ALWAYS_HAD = ("exams", "payroll", "accounting", "library", "inventory")


def grant_what_schools_had(apps, schema_editor):
    Module = apps.get_model("main", "Module")
    SchoolAdmin = apps.get_model("main", "SchoolAdmin")
    SchoolModule = apps.get_model("main", "SchoolModule")
    for code, name in CATALOG:
        Module.objects.get_or_create(code=code, defaults={"name": name})
    rows = []
    schools = SchoolAdmin.objects.values_list("id", "uses_hostel", "uses_extra_billing")
    for school_id, hostel, extra_billing in schools.iterator():
        codes = [*ALWAYS_HAD, *(["hostel"] if hostel else []),
                 *(["extra_billing"] if extra_billing else [])]
        rows += [SchoolModule(school_id=school_id, module_id=code) for code in codes]
    SchoolModule.objects.bulk_create(rows, batch_size=1000)


def put_the_columns_back(apps, schema_editor):
    """Reverse: hostel / extra billing back onto the school's columns as the
    grants have them, before the tables go."""
    SchoolAdmin = apps.get_model("main", "SchoolAdmin")
    SchoolModule = apps.get_model("main", "SchoolModule")
    for code, column in (("hostel", "uses_hostel"), ("extra_billing", "uses_extra_billing")):
        have = SchoolModule.objects.filter(module_id=code, is_active=True).values("school_id")
        SchoolAdmin.objects.exclude(id__in=have).update(**{column: False})
        SchoolAdmin.objects.filter(id__in=have).update(**{column: True})


